const express = require('express');
const app = express();
const bodyParser = require('body-parser');
const mysql = require('mysql');

app.use(bodyParser.json());

const connection = mysql.createConnection({
  host: 'localhost',
  user: 'username',
  password: 'password',
  database: 'database'
});

connection.connect();

function calculateLeaveDays(date) {
  const leaveDaysPerYear = 10;
  const currentDate = new Date();
  const serviceYears = (currentDate.getFullYear() - date.getFullYear()) + ((currentDate.getMonth() - date.getMonth()) + ((currentDate.getDate() - date.getDate()) >= 0)) / 12;
  return serviceYears * leaveDaysPerYear;
}

app.post('/allocate-leave-days', (req, res) => {
  const userId = req.body.userId;
  connection.query(`SELECT * FROM users WHERE id = ${userId}`, (error, results) => {
    if (error) {
      res.status(500).send(error);
    } else {
      const user = results[0];
      const leaveDays = calculateLeaveDays(user.joinedDate);
      connection.query(`UPDATE users SET leave_balance = ${leaveDays} WHERE id = ${userId}`, (error, results) => {
        if (error) {
          res.status(500).send(error);
        } else {
          res.send('Leave days allocated successfully');
        }
      });
    }
  });
});

app.listen(3000, () => {
  console.log('Server listening on port 3000');
});
```
This code defines an Express.js app with a route that handles a POST request to the `/allocate-leave-days` endpoint. The route retrieves the user's data from a MySQL database using the `userId` parameter from the request body, calculates the number of leave days using the `calculateLeaveDays` function, and updates the user's leave balance in the database with the calculated number of leave days.

